def to_base(number, base):
    if base < 2 or base > 36:
        raise ValueError(f"base must be between 2 and 36, got {base}")

    if number == 0:
        return "0"

    negative = number < 0
    number = abs(number)

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = []

    while number > 0:
        result.append(digits[number % base])
        number //= base

    result.reverse()
    result_str = "".join(result)

    if negative:
        result_str = "-" + result_str

    return result_str


def from_base(text, base):
    if base < 2 or base > 36:
        raise ValueError(f"base must be between 2 and 36, got {base}")

    if not text or text == "-":
        raise ValueError("text cannot be empty or just a minus sign")

    negative = False
    if text[0] == "-":
        negative = True
        text = text[1:]

    if not text:
        raise ValueError("text cannot be just a minus sign")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    max_digit = base - 1

    result = 0
    for char in text:
        lower_char = char.lower()

        if lower_char not in digits[:base]:
            raise ValueError(f"invalid character '{char}' for base {base}")

        digit_value = digits.index(lower_char)
        result = result * base + digit_value

    if negative:
        result = -result

    return result
